// WIFI
// =============================

void connectWiFi()
{
    WiFi.begin(
        WIFI_SSID,
        WIFI_PASSWORD
    );

    Serial.print("Connecting WiFi");

    while (
        WiFi.status() != WL_CONNECTED
    )
    {
