    }

    if (
        duration >= 1000 &&
        duration <= 30000
    )
    {
        manualDuration = duration;
    }

    bool manualWater =
        database.get<bool>(
            aClient,
            base + "manual_water"
        );

    // =============================
    // MANUAL MODE
    // =============================

    if (
        controlMode == "manual" &&
        manualWater
    )
    {
        pumpOn();

        delay(
            manualDuration
        );

