        "/smart_garden/zones/zone_a/pump/last_started_at",
        getUnixTime()
    );

    Serial.println("PUMP ON");
}

void pumpOff()
{
    digitalWrite(
        RELAY_PIN,
        RELAY_OFF
    );

    if (!pumpRunning)
        return;

    pumpRunning = false;

    database.set<bool>(
        aClient,
        "/smart_garden/zones/zone_a/pump/status",
        false
    );

    database.set<int>(
        aClient,
        "/smart_garden/zones/zone_a/pump/last_stopped_at",
        getUnixTime()
    );

    Serial.println("PUMP OFF");
}

// =============================
// SOIL
// =============================

int readSoilMoisture()
{
    int raw = analogRead(
        SOIL_PIN
    );

    int percent = map(
        raw,
        SOIL_DRY,
        SOIL_WET,
        0,
        100
    );

    return constrain(
        percent,
        0,
        100
    );
}

// =============================
// SEND SENSOR
// =============================

void sendSensorData()
{
    int soilRaw =
        analogRead(SOIL_PIN);

    int soil =
        map(
            soilRaw,
            SOIL_DRY,
            SOIL_WET,
            0,
            100
        );

    soil = constrain(
        soil,
        0,
        100
    );

    float temperature =
        dht.readTemperature();

    float humidity =
        dht.readHumidity();

    float light =
        lightMeter.readLightLevel();

    String path =
        "/smart_garden/zones/zone_a/sensors/";

    database.set<int>(
        aClient,
        path + "soil_raw",
        soilRaw
    );

    database.set<int>(
        aClient,
        path + "soil_moisture",
        soil
    );

    if (!isnan(temperature))
    {
        database.set<number_t>(
            aClient,
            path + "temperature",
            number_t(
                temperature,
                1
            )
        );
    }

    if (!isnan(humidity))
    {
        database.set<number_t>(
            aClient,
            path + "humidity",
            number_t(
                humidity,
                1
            )
        );
    }

    if (light >= 0)
    {
        database.set<number_t>(
            aClient,
            path + "light",
            number_t(
                light,
                0
            )
        );
    }

    database.set<int>(
        aClient,
        path + "updated_at",
        getUnixTime()
    );

    database.set<int>(
        aClient,
        "/smart_garden/zones/zone_a/device/last_seen",
        getUnixTime()
    );

    database.set<bool>(
        aClient,
        "/smart_garden/zones/zone_a/device/online",
        true
    );

    Serial.println(
        "Sensor data uploaded"
    );
}

// =============================
// READ CONTROL
// =============================

void readControl()
{
    String base =
        "/smart_garden/zones/zone_a/control/";

    String mode =
        database.get<String>(
            aClient,
            base + "mode"
        );

    if (
        mode == "auto" ||
        mode == "manual"
    )
    {
        controlMode = mode;
    }

    int start =
        database.get<int>(
            aClient,
            base + "moisture_start"
        );

    int stop =
        database.get<int>(
            aClient,
            base + "moisture_stop"
        );

    int duration =
        database.get<int>(
            aClient,
            base + "manual_duration_ms"
        );

    if (
        start >= 0 &&
        start <= 100
    )
    {
        moistureStart = start;
    }

    if (
        stop >= moistureStart &&
        stop <= 100
    )
    {
        moistureStop = stop;
    }

    if (
        duration >= 1000 &&
        duration <= 30000
    )
    {
        manualDuration = duration;
    }

    bool manualWater =
        database.get<bool>(
            aClient,
            base + "manual_water"
        );

    // =============================
    // MANUAL MODE
    // =============================

    if (
        controlMode == "manual" &&
        manualWater
    )
    {
        pumpOn();

        delay(
            manualDuration
        );

        pumpOff();

        database.set<bool>(
            aClient,
            base + "manual_water",
            false
        );

        return;
    }

    // =============================
    // AUTO MODE
    // =============================

    if (controlMode == "auto")
    {
        int soil =
            readSoilMoisture();

        bool cooldownFinished =
            millis() - lastAutoStop >
            AUTO_COOLDOWN;

        if (
            !pumpRunning &&
            soil <= moistureStart &&
            cooldownFinished
        )
        {
            pumpOn();
        }

        if (
            pumpRunning &&
            soil >= moistureStop
        )
        {
            pumpOff();

            lastAutoStop =
                millis();
        }
    }
}

// =============================
// SAFETY
// =============================

void pumpSafety()
{
    if (!pumpRunning)
        return;

    if (
        millis() - pumpStartedAt >
        MAX_PUMP_RUNTIME
    )
    {
        Serial.println(
            "MAX PUMP RUNTIME"
        );

        pumpOff();

        lastAutoStop =
            millis();
    }
}

// =============================
// SETUP
// =============================

void setup()
{
    Serial.begin(115200);

    pinMode(
        RELAY_PIN,
        OUTPUT
    );

    digitalWrite(
        RELAY_PIN,
        RELAY_OFF
    );

    dht.begin();

    Wire.begin(
        SDA_PIN,
        SCL_PIN
    );

    lightMeter.begin();

    connectWiFi();

