    configTime(
        0,
        0,
        "pool.ntp.org",
        "time.google.com"
    );

    sslClient.setInsecure();

    sslClient.setConnectionTimeout(
        1000
    );

    sslClient.setHandshakeTimeout(
        5
    );

    initializeApp(
        aClient,
        app,
        getAuth(userAuth),
        120000
    );

    app.getApp<RealtimeDatabase>(
        database
    );

    database.url(
        DATABASE_URL
    );

    Serial.println(
        "Firebase initialized"
    );
}

