    input.nowMs = nowMs;
    input.unixSeconds = 2'000'000'000ULL;
    input.timeTrusted = true;
    input.wifiConnected = true;
    input.authenticated = true;
    input.controlValid = true;
    input.controlReceivedAtMs = nowMs;
    input.soilValid = true;
    input.soilPercent = 50;
